mapper.select:
SELECT
FROM lease_order o LEFT JOIN store s ON s.id = o.store_id AND s.deleted = 0 WHERE o.deleted = 0 AND o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.create_time DESC, o.id DESC

SELECT , u.username AS customer_username, u.real_name AS customer_name, u.phone AS customer_phone FROM lease_order o LEFT JOIN store s ON s.id = o.store_id AND s.deleted = 0 LEFT JOIN sys_user u ON u.id = o.user_id AND u.deleted = 0 WHERE o.deleted = 0 AND o.store_id = #{storeId}
AND o.status = #{status}
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM sys_user u WHERE u.id = o.user_id AND u.deleted = 0 AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%')) ) )
ORDER BY o.create_time DESC, o.id DESC
